"""Post-seal, descriptive mechanism analysis; no method or threshold changes."""
from pathlib import Path
import json,numpy as np
R=Path(__file__).resolve().parents[2];H=R/'research/round129';O=H/'scores_attempt001';rd=lambda p:json.loads(Path(p).read_text())
def dump(p,x):p.write_text(json.dumps(x,indent=2,allow_nan=False)+'\n')
def compare(rows,k,c):
 d=np.array([r['arms'][k]['IoU']-r['arms'][c]['IoU'] for r in rows]);return {'n':len(rows),'gain_pp':float(d.mean()*100) if len(d) else 0.,'better':int((d>1e-12).sum()),'worse':int((d< -1e-12).sum()),'same':int((abs(d)<=1e-12).sum()),'query_changes':sum(r['arms'][k]['query_PRIVATE']!=r['arms'][c]['query_PRIVATE'] for r in rows)}
def main():
 rows=[r for f in sorted(O.glob('*_ALL_ROWS_PRIVATE.json')) for r in rd(f)];assert len(rows)==2304;process=rd(H/'PROCESS_ROWS_PRIVATE.json');summary=[];quality=[];subsets=[];cases=[]
 for co in ['DEV','EXP']:
  rr=[r for r in rows if r['cohort']==co];eligible=[r for r in rr if r['scope_eligible']];part=[r for r in rr if r['partial_eligible']];plain=[r for r in rr if not r['protected_alias_fallback']]
  for label,rs in [('all',rr),('supported',eligible),('partial',part),('R127_global_good',[r for r in rr if r['arms']['R127_global_F']['IoU']>r['arms']['zero_F']['IoU']+1e-12]),('R127_global_bad',[r for r in rr if r['arms']['R127_global_F']['IoU']<r['arms']['zero_F']['IoU']-1e-12]),('teacher_worse',[r for r in rr if r['diagnostics'].get('teacher_worse_than_zero')]),('teacher_kept_source_query',[r for r in rr if r['diagnostics'].get('teacher_kept_zero_query')])]:
   for k,c in [('global_scope_F','zero_F'),('conditional_F','zero_F'),('partial_F','zero_F'),('partial_guard_F','zero_F'),('partial_guard_F','partial_F'),('partial_guard_F','wrong_guard_F'),('partial_guard_F','direct_partial_F'),('partial_guard_C','zero_C')]:subsets.append({'cohort':co,'subset':label,'method':k,'control':c,**compare(rs,k,c)})
  rec=[r for r in part if r['diagnostics']['partial_eligible_recoverable_source_error']];inside=[r for r in part if r['diagnostics']['q0_in_S']];excluded=[r for r in inside if not r['diagnostics']['q0_in_C']]
  quality.append({'cohort':co,'n':len(rr),'protected_aliases':sum(r['protected_alias_fallback'] for r in rr),'scope_eligible':len(eligible),'partial_eligible':len(part),'oracle_Acc25_nonalias':sum(r['diagnostics']['oracle_Acc25'] for r in plain),'partial_recoverable_zero_errors':len(rec),'recoverable_errors_C_has_Acc25':sum(r['diagnostics']['C_has_Acc25_candidate'] for r in rec),'partial_q0_in_S':len(inside),'partial_q0_excluded_from_C':len(excluded),'excluded_q0_good_Acc25':sum(r['arms']['zero_F']['IoU']>.25 for r in excluded),'partial_C_retains_best_in_S':sum(r['diagnostics']['C_retains_best_in_S'] for r in part),'partial_S_contains_global_best':sum(r['diagnostics']['S_contains_global_best_IoU'] for r in part),'partial_C_contains_global_best':sum(r['diagnostics']['C_contains_global_best_IoU'] for r in part),'partial_S_has_Acc25':sum(r['diagnostics']['S_has_Acc25_candidate'] for r in part),'partial_C_has_Acc25':sum(r['diagnostics']['C_has_Acc25_candidate'] for r in part),'partial_wrong_scope_changed_inputs':sum(r['scope_metadata']['scope_changed_by_permutation']>0 for r in part),'partial_wrong_label_changed_inputs':sum(r['scope_metadata']['labels_changed_by_permutation']>0 for r in part),'primary_top1_same_as_unguarded':sum(r['arms']['partial_guard_F']['query_PRIVATE']==r['arms']['partial_F']['query_PRIVATE'] for r in rr),'primary_top1_same_as_wrong':sum(r['arms']['partial_guard_F']['query_PRIVATE']==r['arms']['wrong_guard_F']['query_PRIVATE'] for r in rr)})
  for kind in ['conditional','partial','partial_guard','wrong_guard']:
   pp=[p for p in process if p['cohort']==co and p['setting']==kind];active=[p for p in pp if p['active']];summary.append({'cohort':co,'setting':kind,'total_denominator':len(rr),'supported_denominator':len(pp),'active_inputs':len(active),'nonzero_inputs':sum(p['parameter_L2']>0 for p in pp),'accepted_steps':sum(p['accepted_steps'] for p in pp),'constraint_rejected_trials':sum(p['constraint_rejected_trials'] for p in pp),'Armijo_rejected_trials':sum(p['Armijo_rejected_trials'] for p in pp),'mean_active_parameter_L2':float(np.mean([p['parameter_L2'] for p in active])) if active else 0.,'max_unknown_KL':max([p['unknown_KL'] for p in pp],default=0.)})
  for k,c in [('partial_guard_F','zero_F'),('partial_guard_F','direct_partial_F'),('partial_guard_F','partial_F'),('partial_guard_F','wrong_guard_F'),('conditional_F','zero_F'),('partial_guard_C','zero_C')]:
   changed=[r for r in rr if abs(r['arms'][k]['IoU']-r['arms'][c]['IoU'])>1e-12]
   for r in changed:cases.append({'cohort':co,'source':r['source'],'target':r['target'],'id_PRIVATE':r['id_PRIVATE'],'scene_PRIVATE':r['scene_PRIVATE'],'method':k,'control':c,'baseline_IoU':r['arms'][c]['IoU'],'adapted_IoU':r['arms'][k]['IoU'],'delta_IoU':r['arms'][k]['IoU']-r['arms'][c]['IoU'],'scope_eligible':r['scope_eligible'],'partial_eligible':r['partial_eligible'],'teacher_worse':r['diagnostics'].get('teacher_worse_than_zero',False),'teacher_kept_source_query':r['diagnostics'].get('teacher_kept_zero_query',False),'identity_audit':'not inferred from IoU or geometry group'})
 dump(H/'PROCESS_SUMMARY.json',summary);dump(H/'SET_QUALITY.json',quality);dump(H/'SUBSET_COMPARISONS.json',subsets);dump(H/'CHANGED_CASES_PRIVATE.json',cases);print(json.dumps({'process':summary,'set_quality':quality},indent=2))
if __name__=='__main__':main()
